function normalizeAnswer(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[.!?。！？]+$/g, "")
    .replace(/\s+/g, " ");
}

interface DrillQuestion {
  id: string;
  source: "bank" | "custom";
  moduleId?: string;
  kind: string;
  prompt: string;
  options: string[];
  answer: string;
  acceptedAnswers: string[];
  explanationZh: string;
  /** 题库题带原 PracticeItem，用于记学习台账；自建题没有。 */
  item?: PracticeItem;
}

/** 每道题一格子状态：翻走了再翻回来，勾的选项、判的分、解析都还在。 */
interface DrillAnswer {
  text: string;
  checked: boolean | null;
  feedback: string | null;
}

const EMPTY_ANSWER: DrillAnswer = { text: "", checked: null, feedback: null };

/** 页眉上那枚题型小标：题库里的英文 kind 换成人话。 */
const KIND_LABELS: Record<string, string> = {
  "multiple-choice": "选择题",
  "true-false": "判断题",
  "short-answer": "简答题",
  matching: "连线题",
  spelling: "拼写",
  translation: "翻译",
  writing: "写作",
};

// 页序列：0 封里 · 1 题卷目录 · 2.. 一页一题。
const PAGE_TOC = 1;
const QUESTION_START = 2;

function seedFrom(value: string, extra: number) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash = Math.imul(hash ^ value.charCodeAt(index), 16777619);
  }
  return (hash ^ Math.imul(extra + 1, 2654435761)) >>> 0;
}

/** 种子洗牌：换章节/换顺序/点重新开始才重排，加自建题不打断当前题序。 */
function seededShuffle<T>(items: T[], seed: number): T[] {
  let state = seed >>> 0;
  const nextRandom = () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
  const next = [...items];
  for (let i = next.length - 1; i > 0; i -= 1) {
    const j = Math.floor(nextRandom() * (i + 1));
    [next[i], next[j]] = [next[j]!, next[i]!];
  }
  return next;
}

interface DrillSheetProps {
  question: DrillQuestion;
  index: number;
  total: number;
  entry: DrillAnswer;
  fitKey: string;
  tokens: ReaderTextTokenRange[];
  onAnswerText: (question: DrillQuestion, text: string) => void;
  onCheck: (question: DrillQuestion) => void;
  onNext: () => void;
  onWord: (
    event: ReactMouseEvent<HTMLButtonElement>,
    token: ReaderTextTokenRange,
    text: string,
  ) => void;
}

/**
 * 一页一道题。抽成 memo 组件：一个字母一个字母敲的时候，
 * 只有正在答的那页重画，别的页（几十张）不用跟着动。
 */
const DrillSheet = memo(function DrillSheet({
  question,
  index,
  total,
  entry,
  fitKey,
  tokens,
  onAnswerText,
  onCheck,
  onNext,
  onWord,
}: DrillSheetProps) {
  const answered = entry.checked !== null;
  const isCorrect = entry.checked === true;
  const correctOption = (option: string) =>
    normalizeAnswer(option) === normalizeAnswer(question.answer);

  return (
    <div className="book-page">
      <div className="book-page__body">
        <div className="page-fit page-fit--center" data-fit={fitKey}>
          <section className="drill-sheet">
            <header className="drill-sheet__head">
              <span className="drill-sheet__kind">
                {question.source === "custom"
                  ? "自建题"
                  : KIND_LABELS[question.kind] ?? question.kind}
              </span>
              <small>
                第 {index + 1} 题 · 共 {total} 题
              </small>
            </header>

            <strong className="drill-sheet__prompt">
              {tokens.map((token, tokenIndex) =>
                token.isWord ? (
                  <button
                    key={`${tokenIndex}-${token.start}`}
                    type="button"
                    className="drill-sheet__word"
                    onClick={(event) => onWord(event, token, question.prompt)}
                  >
                    {token.value}
                  </button>
                ) : (
                  <span key={`${tokenIndex}-${token.start}`}>{token.value}</span>
                ),
              )}
            </strong>

            {question.options.length ? (
              <div className="drill-sheet__options">
                {question.options.map((option) => (
                  <label
                    key={option}
                    className={cn(
                      entry.text === option && "is-picked",
                      answered && correctOption(option) && "is-answer",
                    )}
                  >
                    <input
                      type="radio"
                      name={`drill-${question.id}`}
                      checked={entry.text === option}
                      disabled={answered}
                      onChange={() => onAnswerText(question, option)}
                    />
                    <span>{option}</span>
                  </label>
                ))}
              </div>
            ) : (
              <input
                className="drill-sheet__input"
                value={entry.text}
                disabled={answered}
                placeholder="Write your answer…"
                aria-label={`第 ${index + 1} 题作答`}
                onChange={(event) => onAnswerText(question, event.target.value)}
                onKeyDown={(event) => {
                  if (event.key !== "Enter") return;
                  event.preventDefault();
                  if (answered) onNext();
                  else onCheck(question);
                }}
              />
            )}

            {/* 判分块一直在版面上占着位（没答时隐着），
                这样翻开页量高度和答完之后一样，解析不会把页撑破。 */}
            <p
              className={cn(
                "drill-sheet__feedback",
                answered && !isCorrect && "is-wrong",
                !entry.feedback && "is-empty",
              )}
              aria-live="polite"
            >
              {isCorrect ? <Check size={14} /> : <CircleHelp size={14} />}
              {entry.feedback ?? " "}
            </p>

            <div className="drill-sheet__actions">
              {answered ? (
                <button
                  type="button"
                  className="drill-sheet__button"
                  onClick={onNext}
                >
                  <ChevronRight size={14} />
                  {index + 1 >= total ? "做完了 · 合上题卷" : "下一题"}
                </button>
              ) : (
                <button
                  type="button"
                  className="drill-sheet__button"
                  disabled={!entry.text.trim()}
                  onClick={() => onCheck(question)}
                >
                  <CircleHelp size={14} />
                  检查答案
                </button>
              )}
            </div>
          </section>
        </div>
      </div>
    </div>
  );
});

export function PracticeDrillPage() {
  const { trackId } = useParams();
  const navigate = useNavigate();
  const track = practiceTrackById(trackId);
  const book = knowledgeBookById(track?.bookId);
  const hydrate = useKnowledge((state) => state.hydrate);
  const recordAttempt = useKnowledge((state) => state.recordAttempt);

  const bookHandle = useRef<FlipBookHandle | null>(null);

  const [moduleFilter, setModuleFilter] = useState<string>("all");
  const [orderMode, setOrderMode] = useState<"random" | "sequence">("random");
  const [queueSeed, setQueueSeed] = useState(0);
  const [answers, setAnswers] = useState<Record<string, DrillAnswer>>({});
  const [score, setScore] = useState({ correct: 0, wrong: 0 });
  const [customQuestions, setCustomQuestions] = useState<CustomPracticeQuestion[]>(
    loadCustomQuestions,
  );
  const [composerOpen, setComposerOpen] = useState(false);
  /** 题干里点开的那个词（词典卡片贴在它旁边）。 */
  const [lookup, setLookup] = useState<{
    word: string;
    contextBefore: string;
    contextAfter: string;
    x: number;
    y: number;
    drawer: boolean;
  } | null>(null);
  const [draftPrompt, setDraftPrompt] = useState("");
  const [draftAnswer, setDraftAnswer] = useState("");
  const [draftExplanation, setDraftExplanation] = useState("");

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  useEffect(() => {
    if (!track) return;
    recordStudyEvent({ kind: "open", at: Date.now(), bookId: track.bookId });
  }, [track]);

  const bank = useMemo<DrillQuestion[]>(() => {
    if (!book) return [];
    return practiceForBook(book).map((item) => ({
      id: item.id,
      source: "bank" as const,
      moduleId: moduleForNode(book, item.nodeId)?.id,
      kind: item.kind,
      prompt: item.prompt,
      options: item.options,
      answer: item.answer,
      acceptedAnswers: item.acceptedAnswers,
      explanationZh: item.explanationZh,
      item,
    }));
  }, [book]);

  const customAsQuestions = useMemo<DrillQuestion[]>(() => {
    if (!track) return [];
    return customQuestions
      .filter((question) => question.trackId === track.id)
      .map((question) => ({
        id: question.id,
        source: "custom" as const,
        kind: "short-answer",
        prompt: question.prompt,
        options: [],
        answer: question.answer,
        acceptedAnswers: [],
        explanationZh: question.explanationZh,
      }));
  }, [customQuestions, track]);

  const orderedBank = useMemo(() => {
    const filtered = bank.filter(
      (question) => moduleFilter === "all" || question.moduleId === moduleFilter,
    );
    if (orderMode !== "random") return filtered;
    return seededShuffle(filtered, seedFrom(moduleFilter, queueSeed));
  }, [bank, moduleFilter, orderMode, queueSeed]);

  // 自建题始终排在题库题后面，增删不会打乱题库题的当前顺序。
  const activeQuestions = useMemo(
    () => [...orderedBank, ...customAsQuestions],
    [orderedBank, customAsQuestions],
  );

  // 题干分词算一次就够：敲键盘的时候不用把几十道题重新切一遍。
  const promptTokens = useMemo(
    () =>
      new Map(
        activeQuestions.map((question) => [
          question.id,
          tokenizeReaderTextWithOffsets(question.prompt),
        ]),
      ),
    [activeQuestions],
  );

  const total = activeQuestions.length;

  // 判分要读最新一版答案，但又不想让回调跟着答案变（memo 的页会全部重画）：
  // 用 ref 兜住最新值。
  const answersRef = useRef(answers);
  answersRef.current = answers;

  /** 翻到第 page 页（宽屏按纸号落位，窄屏一页一号）。 */
  const flipToPage = useCallback((page: number) => {
    const handle = bookHandle.current;
    if (!handle) return;
    handle.flipTo(handle.isSingle() ? page : Math.floor(page / 2));
  }, []);

  const onAnswerText = useCallback(
    (question: DrillQuestion, text: string) => {
      setAnswers((map) => ({
        ...map,
        [question.id]: { ...(map[question.id] ?? EMPTY_ANSWER), text },
      }));
    },
    [],
  );

  const onCheck = useCallback(
    (question: DrillQuestion) => {
      const entry = answersRef.current[question.id] ?? EMPTY_ANSWER;
      if (!entry.text.trim() || entry.checked !== null || !book) return;
      const correct = [question.answer, ...question.acceptedAnswers].some(
        (candidate) => normalizeAnswer(candidate) === normalizeAnswer(entry.text),
      );
      setAnswers((map) => ({
        ...map,
        [question.id]: {
          ...entry,
          checked: correct,
          feedback: `${correct ? "Correct. " : "Not quite. "}${
            question.explanationZh || `参考答案：${question.answer}`
          }`,
        },
      }));
      setScore((state) => ({
        correct: state.correct + (correct ? 1 : 0),
        wrong: state.wrong + (correct ? 0 : 1),
      }));
      if (question.item) {
        recordAttempt(question.item, book.id, entry.text, correct);
        recordStudyEvent({
          kind: "knowledge-review",
          at: Date.now(),
          bookId: book.id,
          nodeId: question.item.nodeId,
          correct,
        });
      }
    },
    [book, recordAttempt],
  );

  // 往后翻一张；已经在最后一页再往后 = 合上题卷（封底上写着总分）。
  const onNext = useCallback(() => {
    bookHandle.current?.next();
  }, []);

  /**
   * 题干里点一个词 → 就地翻开词典（练习页没有 AI 面板，
   * 那张卡片上「AI 语境解读」那一格自然收起来）。答案与解析不动。
   */
  const onWord = useCallback(
    (
      event: ReactMouseEvent<HTMLButtonElement>,
      token: ReaderTextTokenRange,
      text: string,
    ) => {
      const rect = event.currentTarget.getBoundingClientRect();
      const placeAbove = rect.top > 320;
      setLookup({
        word: token.value,
        contextBefore: text.slice(Math.max(0, token.start - 180), token.start),
        contextAfter: text.slice(token.end, token.end + 180),
        x: Math.max(12, Math.min(window.innerWidth - 392, rect.left - 20)),
        y: Math.min(
          window.innerHeight - 560,
          placeAbove ? rect.top - 300 : rect.bottom + 12,
        ),
        drawer: window.innerWidth < 720,
      });
    },
    [],
  );

  if (!track || !book) return <Navigate to="/shelf" replace />;

  const answered = score.correct + score.wrong;
  const accuracy = answered
    ? Math.round((score.correct / answered) * 100)
    : 0;

  /** 换章节/换题序/重新开始之后，从头一页（题卷目录）重新翻起。 */
  const resetToToc = () => {
    flipToPage(PAGE_TOC);
  };

  const pickModule = (id: string) => {
    setModuleFilter(id);
    resetToToc();
  };

  const toggleOrder = () => {
    setOrderMode((mode) => (mode === "random" ? "sequence" : "random"));
    resetToToc();
  };

  const restart = () => {
    setAnswers({});
    setScore({ correct: 0, wrong: 0 });
    setQueueSeed((seed) => seed + 1);
    resetToToc();
  };

  const goToQuestion = (index: number) => {
    if (!total) return;
    flipToPage(QUESTION_START + (((index % total) + total) % total));
  };

  const addCustomQuestion = () => {
    const prompt = draftPrompt.trim();
    const answerText = draftAnswer.trim();
    if (!prompt || !answerText) return;
    const question = createCustomQuestion({
      trackId: track.id,
      prompt,
      answer: answerText,
      explanationZh: draftExplanation,
    });
    setCustomQuestions((currentQuestions) => {
      const next = [question, ...currentQuestions];
      saveCustomQuestions(next);
      return next;
    });
    setDraftPrompt("");
    setDraftAnswer("");
    setDraftExplanation("");
    setComposerOpen(false);
    recordStudyEvent({
      kind: "topic",
      at: Date.now(),
      bookId: book.id,
      topic: prompt.slice(0, 48),
    });
  };

  const removeCustomQuestion = (id: string) => {
    setCustomQuestions((currentQuestions) => {
      const next = currentQuestions.filter((question) => question.id !== id);
      saveCustomQuestions(next);
      return next;
    });
  };

  const trackCustomQuestions = customQuestions.filter(
    (question) => question.trackId === track.id,
  );

  // —— 书里的页序列 ——
  // 0 封里（这本书是什么）· 1 题卷目录（章节 / 题号 / 自建题）· 2.. 一页一题；
  // 读完最后一题再往后翻就是封底，封底上写着这次的总分。

  const endpaperPage = (
    <div className="book-page" key="endpaper">
      <div className="book-page__body">
        <div
          className="page-fit page-fit--center"
          data-fit={`drill-${track.id}/endpaper`}
        >
          <div className="endpaper">
            <span className="endpaper__glyph" aria-hidden>
              ❧
            </span>
            <h2 className="endpaper__title">{track.titleZh}练习册</h2>
            <p className="endpaper__note">
              {book.zhTitle} · {track.title}
            </p>
            <p className="endpaper__note">
              共 {total} 题 · 一页一道，翻页作答
            </p>
            <ul className="drill-rules">
              <li>目录页点题号跳题，底部「目录」随时回得去。</li>
              <li>答过的题留在页上：翻回来还能看解析。</li>
              <li>自己出的题和题库题排在同一份题卷里。</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );

  const tocPage = (
    <div className="book-page" key="toc">
      <div className="book-page__body">
        <div className="page-fit" data-fit={`drill-${track.id}/toc`}>
          <div className="drill-toc">
            <header className="drill-toc__head">
              <span>Contents</span>
              <h1>{track.titleZh}练习册</h1>
              <p>{track.subtitleZh}</p>
            </header>

            <div className="drill-toc__chapters" aria-label="按章节筛题">
              <button
                type="button"
                className={cn(moduleFilter === "all" && "is-active")}
                onClick={() => pickModule("all")}
              >
                全部
              </button>
              {book.modules.map((module) => (
                <button
                  key={module.id}
                  type="button"
                  className={cn(moduleFilter === module.id && "is-active")}
                  onClick={() => pickModule(module.id)}
                >
                  {module.titleZh}
                </button>
              ))}
            </div>

            {total ? (
              <ol className="drill-toc__grid">
                {activeQuestions.map((question, index) => {
                  const entry = answers[question.id];
                  return (
                    <li key={question.id}>
                      <button
                        type="button"
                        className={cn(
                          entry?.checked === true && "is-correct",
                          entry?.checked === false && "is-wrong",
                        )}
                        onClick={() => goToQuestion(index)}
                        title={question.prompt.slice(0, 48)}
                      >
                        {String(index + 1).padStart(2, "0")}
                      </button>
                    </li>
                  );
                })}
              </ol>
            ) : (
              <p className="drill-toc__empty">
                这一章还没有题。换一个章节，或在下面自己出几道。
              </p>
            )}

            <section className="drill-toc__custom">
              <div className="drill-toc__custom-head">
                <strong>
                  <PenLine size={13} />
                  自己出题 · {trackCustomQuestions.length}
                </strong>
                <button
                  type="button"
                  className="drill-toc__compose"
                  onClick={() => setComposerOpen(true)}
                >
                  <BookmarkPlus size={13} />
                  写一道
                </button>
              </div>
              {trackCustomQuestions.length ? (
                <ul className="drill-toc__custom-list">
                  {trackCustomQuestions.map((question) => (
                    <li key={question.id}>
                      <span>{question.prompt}</span>
                      <button
                        type="button"
                        onClick={() => removeCustomQuestion(question.id)}
                        aria-label="删除这道题"
                      >
                        <Trash2 size={13} />
                      </button>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="drill-toc__empty">
                  还没有自建题；写一道，它排在题库题后面。
                </p>
              )}
            </section>

            <button
              type="button"
              className="drill-toc__book"
              onClick={() => navigate(`/book/${book.id}`)}
            >
              去看知识书 · {book.zhTitle}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const emptyPage = (
    <div className="book-page" key="empty">
      <div className="book-page__body">
        <div
          className="page-fit page-fit--center"
          data-fit={`drill-${track.id}/empty`}
        >
          <div className="drill-empty">
            <CircleHelp size={26} />
            <strong>这一章还没有题</strong>
            <p>换一个章节，或在目录页自己出几道。</p>
          </div>
        </div>
      </div>
    </div>
  );

  const bookPages: ReactNode[] = [endpaperPage, tocPage];
  if (total === 0) {
    bookPages.push(emptyPage);
  } else {
    activeQuestions.forEach((question, index) => {
      bookPages.push(
        <DrillSheet
          key={question.id}
          question={question}
          index={index}
          total={total}
          entry={answers[question.id] ?? EMPTY_ANSWER}
          fitKey={`drill-${track.id}/${question.id}`}
          tokens={promptTokens.get(question.id) ?? []}
          onAnswerText={onAnswerText}
          onCheck={onCheck}
          onNext={onNext}
          onWord={onWord}
        />,
      );
    });
  }

  const statsLabel = (
    <>
      <span className="drill-stats__wide">
        {answered
          ? `对 ${score.correct} / 错 ${score.wrong} · 正确率 ${accuracy}%`
          : `${total} 道题 · 一页一道`}
      </span>
      <span className="drill-stats__narrow">
        {answered
          ? `对 ${score.correct} / 错 ${score.wrong}`
          : `${total} 题`}
      </span>
    </>
  );

  return (
    <div
      className="practice-drill"
      style={{ "--book-accent": track.accent } as CSSProperties}
    >
      <FlipBook
        ref={bookHandle}
        pages={bookPages}
        cover={
          <>
            <small>
              {book.zhTitle} · {track.title}
            </small>
            <strong>{track.titleZh}练习册</strong>
            <em>{track.subtitleZh}</em>
            <span className="book-cover__hint">轻点翻开</span>
          </>
        }
        backCover={
          <>
            <small>{track.title}</small>
            <strong>
              {answered ? `正确率 ${accuracy}%` : "还没开始"}
            </strong>
            <em>
              {answered
                ? `对 ${score.correct} 题 · 错 ${score.wrong} 题 · 共 ${total} 题`
                : `共 ${total} 题 · 下次接着练`}
            </em>
            <span className="book-cover__hint">轻点再翻开</span>
          </>
        }
        accent={track.accent}
        className="book-stage--drill"
        tocLabel="目录"
        onExit={() => navigate("/practice")}
        exitLabel="返回练习册"
        statusLabel={statsLabel}
        actions={
          <>
            <button
              type="button"
              className="drill-pill-button"
              onClick={toggleOrder}
              aria-label={orderMode === "random" ? "切成顺序出题" : "切成随机出题"}
              title={orderMode === "random" ? "切成顺序出题" : "切成随机出题"}
            >
              <Shuffle size={14} />
              <span>{orderMode === "random" ? "随机出题" : "顺序出题"}</span>
            </button>
            <button
              type="button"
              className="drill-pill-button"
              onClick={restart}
              aria-label="重新开始"
              title="重新开始"
            >
              <RotateCcw size={14} />
              <span>重新开始</span>
            </button>
          </>
        }
      />

      {composerOpen && (
        <div
          className="practice-drill__modal"
          role="presentation"
          onClick={() => setComposerOpen(false)}
        >
          <div
            className="practice-drill__dialog"
            role="dialog"
            aria-modal="true"
            aria-label="自己出题"
            onClick={(event) => event.stopPropagation()}
          >
            <header>
              <div>
                <span>New question</span>
                <h2>写一道自己的题</h2>
              </div>
              <button
                type="button"
                className="practice-drill__dialog-close"
                onClick={() => setComposerOpen(false)}
                aria-label="关闭"
              >
                <X size={17} />
              </button>
            </header>
            <label>
              <span>题干</span>
              <textarea
                rows={3}
                value={draftPrompt}
                placeholder="例如：Spell the noun form of 'decide'."
                onChange={(event) => setDraftPrompt(event.target.value)}
              />
            </label>
            <label>
              <span>答案</span>
              <input
                value={draftAnswer}
                placeholder="自动判分用的参考答案"
                onChange={(event) => setDraftAnswer(event.target.value)}
              />
            </label>
            <label>
              <span>解析（可选）</span>
              <input
                value={draftExplanation}
                placeholder="答完之后给自己看的一句话"
                onChange={(event) => setDraftExplanation(event.target.value)}
              />
            </label>
            <button
              type="button"
              className="practice-drill__dialog-add"
              disabled={!draftPrompt.trim() || !draftAnswer.trim()}
              onClick={addCustomQuestion}
            >
              <BookmarkPlus size={14} />
              加入题卷
            </button>
          </div>
        </div>
      )}

      {lookup && (
        <WordLookupFolder
          word={lookup.word}
          contextBefore={lookup.contextBefore}
          contextAfter={lookup.contextAfter}
          x={lookup.x}
          y={lookup.y}
          drawer={lookup.drawer}
          bookId={track.bookId}
          bookLabel={book.zhTitle}
          onClose={() => setLookup(null)}
        />
      )}
    </div>
  );
}
